BEGIN;
DO $$ BEGIN IF current_database() NOT IN('business_platform_cube4_upgrade_qa','business_platform_cube4_fresh_qa') THEN RAISE EXCEPTION 'dedicated Cube4 QA required';END IF;END $$;
SELECT no_plan();
CREATE FUNCTION pg_temp.time_day(d date,qty numeric DEFAULT 0,outcome text DEFAULT 'worked') RETURNS jsonb LANGUAGE sql AS $$
 SELECT jsonb_build_object('date',d,'employee_id','c44a4000-0000-4000-8000-000000000001','employment_id','c44a5000-0000-4000-8000-000000000001','work_instance_id',gen_random_uuid(),'fact_id',gen_random_uuid(),'fact_version',1,'interpretation_id',gen_random_uuid(),'interpretation_version',1,'outcome',outcome,'absence_units',CASE WHEN outcome='worked' THEN 0 ELSE 1-qty END,'leave_units',qty,'worked_minutes',CASE WHEN outcome='worked' THEN 240 ELSE 30 END,'classification_reconciliation_required',false,'leave_bindings','[]'::jsonb)
$$;
-- Authored capture-shaped inputs are arithmetic/reconciliation fixtures, never legal packs or source consumption.
CREATE FUNCTION pg_temp.source_fixture(time_on boolean DEFAULT true,leave_on boolean DEFAULT false) RETURNS jsonb LANGUAGE sql AS $$
 SELECT jsonb_build_object('engine','cube4-review-v4-daily-sources','period',jsonb_build_object('tenant_id','c44a1000-0000-4000-8000-000000000001','employer_id','c44a3000-0000-4000-8000-000000000001','id','c44a8000-0000-4000-8000-000000000001','starts_on','2030-01-25','ends_on','2030-01-26','is_transition',false),
 'employees',jsonb_build_array(jsonb_build_object('name','Synthetic source Employee','code','SOURCES','employment',jsonb_build_object('tenant_id','c44a1000-0000-4000-8000-000000000001','employer_entity_id','c44a3000-0000-4000-8000-000000000001','id','c44a5000-0000-4000-8000-000000000001','employee_id','c44a4000-0000-4000-8000-000000000001','pay_basis','daily','payroll_eligible',true,'start_date','2030-01-01','end_date',NULL))),
 'compensation',jsonb_build_array(jsonb_build_object('id','c44a6000-0000-4000-8000-000000000001','employment_id','c44a5000-0000-4000-8000-000000000001','valid_from','2030-01-01','valid_until',NULL,'amount',100)),
 'assignments',jsonb_build_array(jsonb_build_object('employment_id','c44a5000-0000-4000-8000-000000000001','valid_from','2030-01-01','valid_until',NULL)),
 'inputs',jsonb_build_array(jsonb_build_object('head',jsonb_build_object('id','c44a7000-0000-4000-8000-000000000001','kind','policy'),'version',jsonb_build_object('id','c44a7100-0000-4000-8000-000000000001','revision',1,'status','draft','effective_from','2030-01-01','effective_until',NULL,'data','{"mode":"calendar_days"}'::jsonb))),
 'packs','[]'::jsonb,'corrections','[]'::jsonb,'optional',jsonb_build_object('time',time_on,'leave',leave_on,'finance','adjustments_only'),
 'optional_sources',jsonb_build_object('contract','cube4-optional-capture-v1','time',jsonb_build_object('enabled',time_on,'items',CASE WHEN time_on THEN jsonb_build_array(pg_temp.time_day('2030-01-25'),pg_temp.time_day('2030-01-26')) ELSE '[]'::jsonb END),'leave',jsonb_build_object('enabled',leave_on,'items','[]'::jsonb)))
$$;
CREATE FUNCTION pg_temp.reconcile(m jsonb) RETURNS jsonb LANGUAGE sql AS $$ SELECT payroll.reconcile_employee_sources(m,m->'employees'->0->'employment') $$;
CREATE FUNCTION pg_temp.employee_result(m jsonb) RETURNS jsonb LANGUAGE sql AS $$ SELECT payroll.build_review(m)->'employees'->0 $$;
CREATE FUNCTION pg_temp.with_choice(m jsonb,source text DEFAULT 'manual',units numeric DEFAULT 1,status text DEFAULT 'approved') RETURNS jsonb LANGUAGE sql AS $$
 SELECT m||jsonb_build_object('inputs',m->'inputs'||jsonb_build_array(jsonb_build_object('head',jsonb_build_object('id','c44a7000-0000-4000-8000-000000000002','kind','manual_units','employment_id','c44a5000-0000-4000-8000-000000000001','period_id','c44a8000-0000-4000-8000-000000000001'),'version',jsonb_build_object('id','c44a7100-0000-4000-8000-000000000002','revision',1,'status',status,'effective_from','2030-01-25','effective_until','2030-01-27','data',jsonb_strip_nulls(jsonb_build_object('source',source,'basis',CASE WHEN source='manual' THEN 'approved_payable_total' END,'units',units))))))
$$;
CREATE FUNCTION pg_temp.half_fixture(paid boolean DEFAULT true,outcome text DEFAULT 'worked') RETURNS jsonb LANGUAGE sql AS $$
 SELECT jsonb_set(jsonb_set(pg_temp.source_fixture(true,true),'{optional_sources,time,items}',jsonb_build_array(pg_temp.time_day('2030-01-25',0.5,outcome)||jsonb_build_object('leave_bindings',jsonb_build_array(jsonb_build_object('request_id','c44a9000-0000-4000-8000-000000000001','approved_preview_version',2,'date','2030-01-25','units',0.5,'mapping_state','mapped','policy_template_id','c44ab000-0000-4000-8000-000000000001','policy_version',3,'algorithm_version',1))),pg_temp.time_day('2030-01-26'))),
 '{optional_sources,leave,items}',jsonb_build_array(jsonb_build_object('request_id','c44a9000-0000-4000-8000-000000000001','approved_preview_version',2,'date','2030-01-25','employee_id','c44a4000-0000-4000-8000-000000000001','employment_id','c44a5000-0000-4000-8000-000000000001','state','approved','effective_units',0.5,'eligible',true,'pay_effect',CASE WHEN paid THEN 'paid' ELSE 'unpaid' END,'is_half_day',true,'mapping_state','mapped','mapping_policy_template_id','c44ab000-0000-4000-8000-000000000001','mapping_policy_version',3,'mapping_algorithm_version',1)))
$$;
SELECT is(pg_temp.reconcile(pg_temp.source_fixture())->'summary'->>'status','reconciliation_ready','two approved worked facts reconcile without Leave enabled');
SELECT is((pg_temp.employee_result(pg_temp.source_fixture())->>'known_gross')::numeric,200::numeric,'two factual worked days create known daily base');
SELECT is((pg_temp.employee_result(pg_temp.half_fixture())->>'known_gross')::numeric,200::numeric,'worked remaining half plus paid Leave half pays one unit');
SELECT is((pg_temp.employee_result(pg_temp.half_fixture(false))->>'known_gross')::numeric,150::numeric,'unpaid Leave half is excluded while remaining work half survives');
SELECT is((pg_temp.reconcile(pg_temp.half_fixture(true,'absence'))->'days'->0->>'absence_units')::numeric,0.5::numeric,'absence quantity already excludes Leave');
SELECT is((pg_temp.employee_result(pg_temp.half_fixture(true,'absence'))->>'known_gross')::numeric,150::numeric,'absence half plus paid Leave half pays Leave only; observed minutes do not fabricate work');
SELECT is((pg_temp.reconcile(pg_temp.half_fixture(true,'absence'))->'days'->0->>'worked_minutes')::numeric,30::numeric,'observed minutes retained independently of classified absence');
SELECT is((pg_temp.employee_result(pg_temp.with_choice(pg_temp.half_fixture(),'manual',1))->>'known_gross')::numeric,100::numeric,'approved manual payable total already includes Leave and is not added twice');
SELECT ok(pg_temp.employee_result(pg_temp.with_choice(pg_temp.source_fixture(),NULL,1))->'issues' @> '[{"code":"source_choice_required"}]','legacy manual and new Time require renewed explicit choice');
SELECT ok(pg_temp.employee_result(pg_temp.with_choice(pg_temp.source_fixture(),'time',0,'draft'))->'issues' @> '[{"code":"source_choice_pending"}]','pending choice cannot be bypassed by default Time');
SELECT is((pg_temp.employee_result(pg_temp.with_choice(pg_temp.source_fixture(),'manual',1,'cancelled'))->>'known_gross')::numeric,200::numeric,'cancelled current choice clears intent without resurrecting an old manual quantity');
SELECT is((pg_temp.employee_result(pg_temp.with_choice(pg_temp.source_fixture(false,false),NULL,1))->>'known_gross')::numeric,100::numeric,'both optional modules disabled preserve existing legacy manual units');
SELECT ok(pg_temp.employee_result(pg_temp.with_choice(pg_temp.source_fixture(false,false),'time',0))->'issues' @> '[{"code":"source_time_disabled"}]','historical Time choice holds with owned manual alternative after entitlement loss');
SELECT is(pg_temp.reconcile(pg_temp.source_fixture(false,false))->'summary'->>'status','disabled','disabled domains have no source interpretation');
SELECT ok(pg_temp.reconcile(jsonb_set(pg_temp.source_fixture(),'{optional_sources,time,items,0,classification_reconciliation_required}','true'))->'issues' @> '[{"code":"source_classification_stale"}]','canonical reconciliation hold is preserved');
SELECT ok(pg_temp.reconcile(jsonb_set(pg_temp.source_fixture(),'{optional_sources,time,items}',jsonb_build_array(pg_temp.time_day('2030-01-25'),pg_temp.time_day('2030-01-25'))))->'issues' @> '[{"code":"source_duplicate_time"}]','duplicate Time instances have no arbitrary winner');
SELECT ok(pg_temp.reconcile(jsonb_set(pg_temp.half_fixture(),'{optional_sources,leave,items,0,approved_preview_version}','3'))->'issues' @> '[{"code":"source_leave_binding_mismatch"}]','approved preview must match exact Time binding');
SELECT ok(pg_temp.reconcile(jsonb_set(pg_temp.half_fixture(),'{optional_sources,leave,items,0,mapping_policy_version}','4'))->'issues' @> '[{"code":"source_mapping_uncertain"}]','halfday mapping versions must match');
SELECT ok(pg_temp.reconcile(jsonb_set(jsonb_set(pg_temp.half_fixture(),'{optional_sources,leave,items,0,state}','"cancelled"'),'{optional_sources,leave,items,0,effective_units}','0'))->'issues' @> '[{"code":"source_leave_binding_mismatch"}]','cancelled Leave contributes zero and invalidates unreconciled Time');
SELECT ok(pg_temp.reconcile(jsonb_set(pg_temp.source_fixture(),'{optional_sources,time,items,0,leave_units}','null'))->'issues' @> '[{"code":"source_quantity_unknown"}]','missing legacy quantity is never assumed zero');
SELECT ok(pg_temp.reconcile(jsonb_set(pg_temp.source_fixture(),'{optional_sources,time,items,0,employee_id}','"c44a4000-0000-4000-8000-000000000099"'))->'issues' @> '[{"code":"source_scope_invalid"}]','capture Employee must match eligible Employment');
SELECT ok(pg_temp.reconcile(jsonb_set(pg_temp.source_fixture(),'{employees,0,employment,employer_entity_id}','"c44a3000-0000-4000-8000-000000000099"'))->'issues' @> '[{"code":"source_scope_invalid"}]','Employer mismatch is refused');
SELECT ok(pg_temp.reconcile(jsonb_set(pg_temp.source_fixture(),'{optional_sources,time,items,0,date}','"2030-01-24"'))->'issues' @> '[{"code":"source_scope_invalid"}]','captured dates must lie inside covered eligible bounds');
SELECT ok(pg_temp.reconcile(jsonb_set(jsonb_set(pg_temp.half_fixture(),'{optional,leave}','false'),'{optional_sources,leave}','{"enabled":false,"items":[]}'))->'issues' @> '[{"code":"source_leave_treatment_unknown"}]','Leave entitlement loss cannot silently classify factual Leave as unpaid');
SELECT is((pg_temp.employee_result(jsonb_set(pg_temp.source_fixture(),'{optional_sources,time,items}',jsonb_build_array(pg_temp.time_day('2030-01-25'))))->>'known_gross')::numeric,100::numeric,'missing civil-date facts are not invented work or unpaid days');
SELECT ok(pg_temp.employee_result(pg_temp.source_fixture())->'issues' @> '[{"code":"source_time_coverage_unqualified"}]','known dated units remain bounded parts without expected-workday coverage qualification');
SELECT is(payroll.build_review(pg_temp.source_fixture())->>'financially_qualified','false','daily source math does not grant legal qualification');
SELECT ok(payroll.build_review(pg_temp.half_fixture())->'issues' @> '[{"code":"time_integration_pending"},{"code":"leave_integration_pending"}]','monthly/overtime/late integration gates remain explicit');
SELECT is(pg_temp.employee_result(pg_temp.source_fixture())->>'gross',NULL::text,'incomplete source coverage never presents authoritative gross');
SELECT ok(NOT(pg_temp.employee_result(pg_temp.half_fixture())->'source_summary')::text ~ 'request_id|fact_id|reason|type_version|mapping_policy','list summary excludes provenance and private detail');
SELECT ok(NOT(pg_temp.employee_result(pg_temp.half_fixture())->'source_days')::text ~ 'request_id|fact_id|reason|type_version|mapping_policy','detail source days carry dates and quantities only');
SELECT is(payroll.review_employee_detail(pg_temp.employee_result(pg_temp.half_fixture()))->'source_days',pg_temp.employee_result(pg_temp.half_fixture())->'source_days','actual detail projection preserves safe source days');
SELECT lives_ok($$SELECT payroll.validate_input('manual_units','{"source":"time","units":0,"reason":"Approved Time basis"}')$$,'explicit Time choice has no manual amount');
SELECT lives_ok($$SELECT payroll.validate_input('manual_units','{"source":"manual","basis":"approved_payable_total","units":1,"reason":"Approved total basis"}')$$,'manual basis is explicit total');
SELECT throws_ok($$SELECT payroll.validate_input('manual_units','{"source":"time","units":1,"reason":"Invalid Time basis"}')$$,'22023','payroll_invalid','Time cannot carry manual quantity');
SELECT throws_ok($$SELECT payroll.validate_input('manual_units','{"source":"time","basis":"approved_payable_total","units":0,"reason":"Invalid Time basis"}')$$,'22023','payroll_invalid','Time cannot carry manual basis');
SELECT throws_ok($$SELECT payroll.validate_input('manual_units','{"source":"manual","units":1,"reason":"Missing total basis"}')$$,'22023','payroll_invalid','new manual choice requires total interpretation');
SELECT throws_ok($$SELECT payroll.validate_input('manual_units','{"source":"unknown","units":1,"reason":"Unknown source"}')$$,'22023','payroll_invalid','source enum is bounded');
SELECT throws_ok($$SELECT payroll.validate_input('manual_units','{"units":0,"reason":"Legacy invalid zero"}')$$,'22023','payroll_invalid','legacy zero remains invalid');
SELECT ok(NOT has_function_privilege('authenticated','payroll.reconcile_employee_sources(jsonb,jsonb)','EXECUTE') AND NOT has_function_privilege('service_role','payroll.daily_source_parts(jsonb,jsonb,jsonb,jsonb,numeric,numeric)','EXECUTE'),'purpose-limited helpers are inaccessible to ordinary and service callers');
-- Dated Time units feed percentage components before rounding; no JS arithmetic.
SELECT set_config('test.dated',jsonb_set(pg_temp.source_fixture(),'{compensation}','[{"id":"c44a6000-0000-4000-8000-000000000001","employment_id":"c44a5000-0000-4000-8000-000000000001","valid_from":"2030-01-01","valid_until":"2030-01-26","amount":100},{"id":"c44a6000-0000-4000-8000-000000000002","employment_id":"c44a5000-0000-4000-8000-000000000001","valid_from":"2030-01-26","valid_until":null,"amount":200}]')::text,true);
SELECT is((pg_temp.employee_result(current_setting('test.dated')::jsonb)->>'known_gross')::numeric,300::numeric,'dated approved Time units support an effective daily rate change');
SELECT set_config('test.percentage',(current_setting('test.dated')::jsonb||jsonb_build_object('inputs',current_setting('test.dated')::jsonb->'inputs'||jsonb_build_array(
 jsonb_build_object('head',jsonb_build_object('id','c44a7000-0000-4000-8000-000000000003','kind','component'),'version',jsonb_build_object('id','c44a7100-0000-4000-8000-000000000003','revision',1,'effective_from','2030-01-01','effective_until',NULL,'data','{"active":true,"name":"Daily percent","classification":"earning","calculation":"percentage","base":"base_pay","behavior":"recurring"}'::jsonb)),
 jsonb_build_object('head',jsonb_build_object('id','c44a7000-0000-4000-8000-000000000004','kind','recurring','employment_id','c44a5000-0000-4000-8000-000000000001'),'version',jsonb_build_object('revision',1,'effective_from','2030-01-01','effective_until',NULL,'data','{"component_id":"c44a7000-0000-4000-8000-000000000003","value":10}'::jsonb)))))::text,true);
SELECT is((pg_temp.employee_result(current_setting('test.percentage')::jsonb)->>'known_gross')::numeric,330::numeric,'percentage uses actual sourced dated base, not old aggregate manual units');
SELECT is((pg_temp.employee_result(jsonb_set(jsonb_set(pg_temp.half_fixture(),'{compensation,0,amount}','0.05'),'{optional_sources,time,items}',jsonb_build_array(pg_temp.half_fixture()->'optional_sources'->'time'->'items'->0)))->>'known_gross')::numeric,0.05::numeric,'half work plus paid half retains exact one-unit tie-safe fraction');
SELECT is((pg_temp.employee_result(jsonb_set(jsonb_set(pg_temp.half_fixture(false),'{compensation,0,amount}','0.05'),'{optional_sources,time,items}',jsonb_build_array(pg_temp.half_fixture(false)->'optional_sources'->'time'->'items'->0)))->>'known_gross')::numeric,0.03::numeric,'half-day 0.025 rounds once away from zero');
