CREATE FUNCTION pg_temp.choice_command(data jsonb,head uuid DEFAULT NULL,expected integer DEFAULT 0,operation text DEFAULT 'save',attempt uuid DEFAULT NULL) RETURNS jsonb LANGUAGE sql AS $$
 SELECT public.payroll_save_input('c44a1000-0000-4000-8000-000000000001','c44a3000-0000-4000-8000-000000000001','manual_units','c44a5000-0000-4000-8000-000000000001',current_setting('test.source_period')::uuid,head,expected,'2030-01-25','2030-02-25',data,operation,COALESCE(attempt,gen_random_uuid()))
$$;
GRANT EXECUTE ON FUNCTION pg_temp.choice_command(jsonb,uuid,integer,text,uuid) TO authenticated;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','c44a0000-0000-4000-8000-000000000001',true);
SELECT set_config('test.source_period',public.payroll_save_calendar('c44a1000-0000-4000-8000-000000000001','c44a3000-0000-4000-8000-000000000001','2030-01-25',24,25,'ending','Africa/Cairo',0,gen_random_uuid(),public.payroll_calendar_preview('c44a1000-0000-4000-8000-000000000001','c44a3000-0000-4000-8000-000000000001','2030-01-25',24,25,'ending','Africa/Cairo'),'Source test calendar')->>'period_id',true);
SELECT is(public.payroll_input_access('c44a1000-0000-4000-8000-000000000001')->>'time_enabled','false','actual input access reports current Attendance availability');
SELECT throws_ok($$SELECT pg_temp.choice_command('{"source":"time","units":0,"reason":"Time source selection"}')$$,'55000','payroll_time_source_disabled','new Time choice cannot be saved while Attendance disabled');
RESET ROLE;
SELECT is((SELECT count(*)::integer FROM payroll.input_heads WHERE tenant_id='c44a1000-0000-4000-8000-000000000001'),0,'disabled Time save has no input effects');
INSERT INTO platform_core.tenant_capability_entitlements(tenant_id,capability_key,is_granted,valid_from,actor_user_id,reason) VALUES('c44a1000-0000-4000-8000-000000000001','hr.attendance',true,now()-interval '1 minute','c44a0000-0000-4000-8000-000000000001','Source QA Attendance');
SET LOCAL ROLE authenticated;
SELECT set_config('test.time_choice',pg_temp.choice_command('{"source":"time","units":0,"reason":"Time source selection"}')::text,true);
SELECT set_config('test.time_head',current_setting('test.time_choice')::jsonb->>'id',true);
SELECT lives_ok($$SELECT pg_temp.choice_command('{"source":"time","units":0,"reason":"Time source selection"}',current_setting('test.time_head')::uuid,1,'approve')$$,'current approved choice uses ordinary CAS and audit');
RESET ROLE;
UPDATE platform_core.tenant_capability_entitlements SET is_granted=false WHERE tenant_id='c44a1000-0000-4000-8000-000000000001' AND capability_key='hr.attendance';
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.payroll_input_workspace('c44a1000-0000-4000-8000-000000000001','c44a3000-0000-4000-8000-000000000001',current_setting('test.source_period')::uuid,'',NULL,NULL,30)$$,'historical read remains available after Attendance loss');
SELECT lives_ok($$SELECT pg_temp.choice_command('{"source":"time","units":0,"reason":"Time source selection"}',current_setting('test.time_head')::uuid,2,'cancel')$$,'current authority can cancel Time choice without Attendance entitlement');
SELECT set_config('test.manual_choice',pg_temp.choice_command('{"source":"manual","basis":"approved_payable_total","units":1,"reason":"Reviewed payable total"}')::text,true);
SELECT lives_ok($$SELECT pg_temp.choice_command('{"source":"manual","basis":"approved_payable_total","units":1,"reason":"Reviewed payable total"}',(current_setting('test.manual_choice')::jsonb->>'id')::uuid,1,'approve')$$,'approved manual alternative is independent of optional Attendance');
RESET ROLE;
SELECT is((SELECT count(*)::integer FROM payroll.command_receipts WHERE tenant_id='c44a1000-0000-4000-8000-000000000001' AND intent->>'kind'='manual_units'),5,'five successful input transitions have one canonical receipt each');
SELECT is((SELECT count(*)::integer FROM payroll.audit_events WHERE tenant_id='c44a1000-0000-4000-8000-000000000001' AND details->>'kind'='manual_units'),5,'five successful input transitions have matching audit evidence');
SELECT is((SELECT count(*)::integer FROM payroll.people_frozen_contexts WHERE tenant_id='c44a1000-0000-4000-8000-000000000001'),0,'candidate choice changes do not consume or freeze People sources');
-- Exact real command text is transformed for structural composition checks only; no Slice7 runtime qualification.
SELECT set_config('test.source_command',pg_get_functiondef('public.payroll_run_command(uuid,uuid,uuid,uuid,integer,text,text,uuid)'::regprocedure),true);
SELECT is(payroll.daily_source_command_definition(replace(current_setting('test.source_command'),'''cube4-review-v4-daily-sources'',manifest,output,a','''cube4-review-v3-source-safe'',manifest,output,a'),false),current_setting('test.source_command'),'unwrapped candidate literal upgrades without changing the rest of the real command');
SELECT set_config('test.wrapped_command',replace(current_setting('test.source_command'),'''cube4-review-v4-daily-sources'',manifest,output,a','manifest->>''engine'',manifest,output,a'),true);
SELECT is(payroll.daily_source_command_definition(current_setting('test.wrapped_command'),true),current_setting('test.wrapped_command'),'known before_advances composition preserves manifest-derived engine including its suffix');
SELECT throws_ok($$SELECT payroll.daily_source_command_definition(current_setting('test.wrapped_command'),false)$$,'P0001','unexpected_daily_source_candidate_identity','manifest-derived identity requires the known wrapper state');
SELECT throws_ok($$SELECT payroll.daily_source_command_definition('unknown candidate identity',true)$$,'P0001','unexpected_daily_source_candidate_identity','unknown insertion shape is refused');
SELECT * FROM finish();
ROLLBACK;
